<?php

namespace Klxm\Tiptap;

/**
 * Base class for profiles from code, see {@see AsProfile}.
 *
 * `config()` returns the same structure as the profile export (JSON) – the addon fills in missing values with the
 * defaults ({@see Profile::DEFAULTS}). The code for a profile assembled in the backend is generated by
 * TipTap-Editor → Profile → „Als PHP-Klasse“.
 */
abstract class ProfileDefinition
{
    /** @return array<string, mixed> */
    abstract public function config(): array;
}
